cat >> src/transport/ws/messageHandler.test.ts <<'EOF'

describe('answering list_sessions when the store fails', () => {
  afterEach(() => setLogger());

  it('answers SERVER_ERROR with no store detail and logs the failure under ws with the session user', async () => {
    const logged: Array<[category: string, fields?: Record<string, unknown>]> = [];
    const ignore = () => undefined;
    setLogger({debug: ignore, info: ignore, warn: ignore, error: (category, _message, fields) => logged.push([category, fields])});
    const sent: OutgoingMessage[] = [];
    const ws = {send: (raw: string) => sent.push(JSON.parse(raw) as OutgoingMessage)} as unknown as WebSocket;
    const store = {listFor: () => Promise.reject(new Error('database offline'))} as unknown as SessionStore;
    const session: ChatSession = {sessionId: 's1', userId: 'u1', entries: []};

    await createMessageHandler({} as ChatOrchestrator, store)(ws, session, {type: 'list_sessions'});

    expect({sent, logged}).toEqual({
      sent: [{type: 'error', code: 'SERVER_ERROR', message: expect.not.stringContaining('database')}],
      logged: [['ws', expect.objectContaining({sessionId: 's1', userId: 'u1', error: 'database offline'})]],
    });
  });
});
EOF
